import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/SentencePiece.html","title":"SentencePiece","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":2.59,"words":776},"filePathRelative":"SentencePiece.md"}`),a={name:`SentencePiece.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="sentencepiece" tabindex="-1"><a class="header-anchor" href="#sentencepiece"><span>SentencePiece</span></a></h1><p><a href="./原論文から解き明かす生成AI.html">原論文から解き明かす生成AI</a></p><ul><li><a href="https://github.com/google/sentencepiece" target="_blank" rel="noopener noreferrer">google/sentencepiece: Unsupervised text tokenizer for Neural Network-based text generation.</a></li><li><a href="./論文.html">論文</a> <a href="https://arxiv.org/abs/1808.06226" target="_blank" rel="noopener noreferrer">arxiv:1808.06226 SentencePiece: A simple and language independent subword tokenizer and detokenizer for Neural Text Processing</a></li></ul><p><a href="./サブワード分割.html">サブワード分割</a>のライブラリ。<a href="./BPE.html">BPE</a>と<a href="./ユニグラム言語モデル.html">ユニグラム言語モデル</a>の実装が入っている、及びその解説論文。</p><h2 id="関連ページ" tabindex="-1"><a class="header-anchor" href="#関連ページ"><span>関連ページ</span></a></h2><p>コードを理解するには<a href="./EnhancedSuffixArray.html">EnhancedSuffixArray</a>を勉強すると良い。<a href="./Heap.html">Heap</a>も復習しておくと良い。ついでに<a href="./SuffixArray.html">SuffixArray</a>も復習（これは不要だが）。</p><h2 id="bpeのトレーニングのコード読み" tabindex="-1"><a class="header-anchor" href="#bpeのトレーニングのコード読み"><span>BPEのトレーニングのコード読み</span></a></h2><p><a href="./原論文から解き明かす生成AI.html">原論文から解き明かす生成AI</a>の問題が2問ほどこれに言及していたので<a href="./BPE.html">BPE</a>のトレーニングのコードを読む。bpe_model_trainer.ccのTrainer::Trainあたり。</p><h3 id="センテンス周辺の型の確認" tabindex="-1"><a class="header-anchor" href="#センテンス周辺の型の確認"><span>センテンス周辺の型の確認</span></a></h3><p>SentenceとSentencesの型は以下。</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line">  <span class="token keyword">using</span> Sentence <span class="token operator">=</span> std<span class="token double-colon punctuation">::</span>pair<span class="token operator">&lt;</span>std<span class="token double-colon punctuation">::</span>string<span class="token punctuation">,</span> <span class="token keyword">int64_t</span><span class="token operator">&gt;</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">using</span> Sentences <span class="token operator">=</span> std<span class="token double-colon punctuation">::</span>vector<span class="token operator">&lt;</span>Sentence<span class="token operator">&gt;</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>int64_tが何なのかは知らないが、とりあえずSentenceはstringだと思っておこう。（追記：freqの計算から予想すると同じ文が何回かあったらそのカウントが入る感じか？）</p><p>sentences_はSetences型なので、だいたい文字列のベクトル。</p><h3 id="シンボル周辺の型の確認" tabindex="-1"><a class="header-anchor" href="#シンボル周辺の型の確認"><span>シンボル周辺の型の確認</span></a></h3><p>Symbolは複雑なので適当に抜粋。</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line">  <span class="token comment">// Symbol represents a character or symbol bigram.</span></span>
<span class="line">  <span class="token keyword">struct</span> <span class="token class-name">Symbol</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> Symbol<span class="token operator">*</span> left <span class="token operator">=</span> <span class="token keyword">nullptr</span><span class="token punctuation">;</span>    <span class="token comment">// left symbol in bigram</span></span>
<span class="line">    <span class="token keyword">const</span> Symbol<span class="token operator">*</span> right <span class="token operator">=</span> <span class="token keyword">nullptr</span><span class="token punctuation">;</span>   <span class="token comment">// right symbol in bigram</span></span>
<span class="line">    string_util<span class="token double-colon punctuation">::</span>UnicodeText chars<span class="token punctuation">;</span>  <span class="token comment">// all flattend chracter sequence</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// Position list. Use set so that we can keep the order of occurrence.</span></span>
<span class="line">    <span class="token comment">// See EncodePos/DecodePos.</span></span>
<span class="line">    absl<span class="token double-colon punctuation">::</span>btree_set<span class="token operator">&lt;</span><span class="token keyword">uint64_t</span><span class="token operator">&gt;</span> positions<span class="token punctuation">;</span></span>
<span class="line">   <span class="token comment">// ... いろいろ省略 ...</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>bigramのシンボルで、それは左と右がそれぞれさらにバイグラムに再帰的になっている構造になっている。 バイグラムじゃない場合はleftもrightもnullでcharsにだけ入る感じになっている。</p><p>ファクトリでキャッシュされて同じ文字列からは同じシンボルになるようになっている。</p><p>symbols_は以下。</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line">  <span class="token comment">// Sentences. symbols_[sid][index] stores a symbol in sentence_[sid][index].</span></span>
<span class="line">  std<span class="token double-colon punctuation">::</span>vector<span class="token operator">&lt;</span>std<span class="token double-colon punctuation">::</span>vector<span class="token operator">&lt;</span>Symbol<span class="token operator">*</span><span class="token operator">&gt;&gt;</span> symbols_<span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>sidはSentencesのインデックスか。だいたい文字列だったので文字列を渡して一文字ずつsymbols_に入れる所から始まる感じだ。</p><h3 id="main-loopの手前までの流れ" tabindex="-1"><a class="header-anchor" href="#main-loopの手前までの流れ"><span>Main Loopの手前までの流れ</span></a></h3><ol><li>Sentencesの中のセンテンスを一文字ずつシンボルとしてsymbols_に入れていく</li><li>全バイグラムをpq（priority queue,ようするに<a href="./Heap.html">Heap</a>）に入れる <ul><li>同じシンボルを一回だけ足すように、全バイグラムを作って見つつはじめて作ったものだけvectorに入れておいて最後にまとめて追加している。</li><li>freqもpositionsから計算する</li></ul></li></ol><p>これでMainLoopが始まる。対象はpqでfreqの順番に取り出す。</p><h3 id="main-loopの流れ" tabindex="-1"><a class="header-anchor" href="#main-loopの流れ"><span>Main Loopの流れ</span></a></h3><p>以下を繰り返す。</p><ol><li>pqから再頻出のシンボルを取る</li><li>final_pieces_に入れてpqから取り除く</li><li>AcceptSymbolを呼ぶ</li><li>pending_queueにあるもののfreqを再計算してpqに入れる <ul><li>ここのpending_queueはAcceptSymbolで新しく作られたペアがあれば入る</li></ul></li></ol><p>AcceptSymbolは後で読む。 ただここまでで、センテンスというのをSymbolの配列として扱って、これを差し替えてマージ処理を行っているのが予想出来る。</p><h3 id="acceptsymbol" tabindex="-1"><a class="header-anchor" href="#acceptsymbol"><span>AcceptSymbol</span></a></h3><p>まずはコードの冒頭のコメントと大枠のfor文の確認から。</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line">absl<span class="token double-colon punctuation">::</span>Status <span class="token class-name">Trainer</span><span class="token double-colon punctuation">::</span><span class="token function">AcceptSymbol</span><span class="token punctuation">(</span>Symbol<span class="token operator">*</span> symbol<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">// Add new bigrams which are created after symbol replacement.</span></span>
<span class="line">  <span class="token comment">// We do not need to scan all characters, but scan the neighbors in</span></span>
<span class="line">  <span class="token comment">// best_symbol.</span></span>
<span class="line">  <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">const</span> <span class="token keyword">uint64_t</span><span class="token operator">&amp;</span> encoded_pos <span class="token operator">:</span> symbol<span class="token operator">-&gt;</span>positions<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>symbolを新しくマージした時の処理をしていて、for文はこのsymbolの現れる所を見ていっている。 オーバーラップのケースとかいろいろ考えるとややこしさもあるが、細かい事は今回は置いとこう。</p><p>ループの中では、主に以下をいろいろする。</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line">    <span class="token comment">// We have three bigrams [prev, left], [left, right], [right, next],</span></span>
<span class="line">    <span class="token comment">// which are affected with this symbol replacement.</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>left, rightをマージする時は、以下のようになる</p><ul><li><code>[prev, left]</code>と<code>[right, next]</code>のペアがなくなる <ul><li>既存のペアのfreqをリセットして再計算させる（減るだけなのでフラグを建ててpqからpopされるまで遅延）</li></ul></li><li><code>[prev, lr]</code> と <code>[lr, right]</code> が出来る</li></ul><p>positionを抜くのかと思ったが、コードを見るとそういう事はしていない。symbolsのindexの所のペアが変わるので、 freqを再計算する時に右隣が自分のペアじゃなくなっていたらそこでpositionsからlazyにeraseしていた。</p><p>eraseなんて大丈夫？と見てみるとpositionsはbtree_setだそうで。</p><h3 id="雑に計算量を考えてみる" tabindex="-1"><a class="header-anchor" href="#雑に計算量を考えてみる"><span>雑に計算量を考えてみる</span></a></h3><p>最初にバイグラムをqueueに入れる所で、バイグラムの個数はN/2なのでO(N)。priority queueはinsertはO(log N)なんだが、ツリーのサイズが最初は小さいのでちゃんと評価するとO(N)（<a href="./Heap.html">Heap</a>の方に教科書の参照あり）。</p><p>sentence pieceはマージの個数次第だが、マージの個数をMとしておこう。</p><p>一回あたりが、pqからのpopにO(log N)、隣を見たり再計算したりはまぁ定数時間だろう。 pqに入れるのはたかだが2個か？と思うとだいたいO(log N)か。 これをM回なので、 雑には O(M log N)。 Mが大きくなるとキューが減るのでもうちょっとtightなバウンドはあるかもしれないが。</p><p>以上から、O(N + M log N)かな？</p><p><a href="./原論文から解き明かす生成AI.html">原論文から解き明かす生成AI</a>ではO(N log N)と言ってるな。 論文にも以下の記述があるが</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Sentence-</span>
<span class="line">Piece adopts an O(N log(N )) algorithm in which</span>
<span class="line">the merged symbols are managed by a binary heap</span>
<span class="line">(priority queue).</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>自分の理解と違うなぁ。 MはNよりはだいぶ小さいと思うのだが。</p><p>コメントにはマージごとに O(log N)と書いてあるな。</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token comment">// Algorithm: O(log N) per merge via:</span></span>
<span class="line"><span class="token comment">//   1. Max-heap for finding the best pair (O(log N) pop vs O(N) scan)</span></span>
<span class="line"><span class="token comment">//   2. Doubly-linked lists for O(1) merge of adjacent tokens</span></span>
<span class="line"><span class="token comment">//   3. Lazy deletion: frequency decrements stored in a &quot;dirty&quot; map,</span></span>
<span class="line"><span class="token comment">//      applied on pop, avoiding O(N) heap search for updates</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>こちらは正しいので、やはり O(M log N)じゃん、と思うのだが。本の回答を見てみる。</p><p><a href="https://github.com/yoheikikuta/support-genAI-book/blob/main/exercises/chapter2.md#%E6%BC%94%E7%BF%92%E5%95%8F%E9%A1%8C211" target="_blank" rel="noopener noreferrer">support-genAI-book/exercises/chapter2.md at main · yoheikikuta/support-genAI-book</a></p><p>いやぁ、Mを最悪Nとか言うのはどうなの？さすがに100GBくらいの学習データとか言っていて、vocabは16kとかなんだからオーダーが全然違うだろう。</p><p>ただBPEをN^2と言うならN log Nと言わないといけないというのはまぁそうだな。</p>`,52)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};